// node --experimental-strip-types --test tests/*.test.ts
// Fixtures in ../fixtures were generated by hemant-shell from a SUPPLIED input
// (the epoch); they are not live readings.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  MAX_SUPPORTED_UNIX_NANOS,
  MIN_SUPPORTED_UNIX_NANOS,
  parseMethodRegistry,
  parseTimeResult,
  snapshotAgeSeconds,
  validateUnixNanosInput,
} from "../lib/contract.ts";

const fixture = (name: string) => JSON.parse(readFileSync(new URL(`../fixtures/${name}`, import.meta.url), "utf8"));
const registry = () => {
  const parsed = parseMethodRegistry(fixture("method-registry.json"));
  assert.ok(parsed.ok);
  return parsed.value;
};

test("registry fixture satisfies the provenance contract; pending methods stay pending", () => {
  const r = registry();
  assert.deepEqual(r.methods.filter((m) => m.status === "pending").map((m) => m.id), ["astronomy-solar-system-positions", "panchanga-ruleset"]);
  for (const m of r.methods) assert.ok(m.limitations.length && m.inputs.length && m.uncertainty);
});

test("registry rejects over-claims, missing fields and duplicates", () => {
  const base = fixture("method-registry.json");
  const variants = [
    { ...base, schema: "hemant.method-registry/2" },
    { ...base, methods: [{ ...base.methods[0], verification: "verified" }] },
    { ...base, methods: [{ ...base.methods[0], uncertainty: "" }] },
    { ...base, methods: [{ ...base.methods[0], extra: 1 }] },
    { ...base, methods: [base.methods[0], base.methods[0]] },
    { ...base, methods: [{ ...base.methods[5], evidence: "host-reported" }] },
  ];
  for (const v of variants) assert.equal(parseMethodRegistry(v).ok, false, JSON.stringify(v).slice(0, 80));
});

test("time-result fixture is valid and every section names an active registry method", () => {
  const parsed = parseTimeResult(fixture("time-result.epoch.json"), registry());
  assert.ok(parsed.ok, parsed.ok ? "" : parsed.error);
  assert.equal(parsed.value.civil.utc, "1979-01-14 07:59:00.000000000 UTC");
  assert.equal(parsed.value.reading.source, "caller-supplied-unix-nanoseconds");
});

test("time-result rejects verification claims, bad ranges and unknown methods", () => {
  const base = fixture("time-result.epoch.json");
  const bad = [
    { ...base, schema: "hemant.time-result/1" },
    { ...base, reading: { ...base.reading, verification: "verified" } },
    { ...base, reading: { ...base.reading, uncertainty: "0 ns" } },
    { ...base, reading: { ...base.reading, unix_nanos: (MAX_SUPPORTED_UNIX_NANOS + 1n).toString() } },
    { ...base, reading: { ...base.reading, unix_nanos: "12; rm -rf" } },
    { ...base, elapsed: { ...base.elapsed, muhurta: 30 } },
    { ...base, methods_used: ["made-up-method"] },
    { ...base, pending: [{ method: "panchanga-ruleset", status: "complete" }] },
  ];
  for (const v of bad) assert.equal(parseTimeResult(v, registry()).ok, false, JSON.stringify(v).slice(0, 120));
  const unknownMethod = { ...base, reading: { ...base.reading, method: "other-v1" }, methods_used: [...base.methods_used, "other-v1"] };
  assert.equal(parseTimeResult(unknownMethod, registry()).ok, false);
});

test("caller input validation accepts only bounded signed integers", () => {
  assert.deepEqual(validateUnixNanosInput(" 285148740000000000 "), { ok: true, value: "285148740000000000" });
  assert.deepEqual(validateUnixNanosInput(MIN_SUPPORTED_UNIX_NANOS.toString()), { ok: true, value: MIN_SUPPORTED_UNIX_NANOS.toString() });
  for (const bad of [null, "", "1e9", "0x10", "--help", "1 --methods-json", "12.5", (MAX_SUPPORTED_UNIX_NANOS + 1n).toString(), "9".repeat(30)]) {
    assert.equal(validateUnixNanosInput(bad).ok, false, String(bad));
  }
});

test("snapshot age uses the client monotonic clock and never goes negative", () => {
  assert.equal(snapshotAgeSeconds(1000, 4500), 3);
  assert.equal(snapshotAgeSeconds(5000, 4000), 0);
});
